insert into public.categories (id, en, bn, hint_en, hint_bn, sensitive, sla_hours, suggested_department_id, active) values ('infrastructure', 'Infrastructure & Road Damage', 'অবকাঠামো ও সড়ক ক্ষতি', 'If the road is unsafe to walk on, say that in the first line.', 'রাস্তায় হাঁটা বিপজ্জনক হলে প্রথম লাইনেই তা লিখুন।', false, 72, 'd-maint', true) on conflict (id) do update set en = excluded.en, bn = excluded.bn, hint_en = excluded.hint_en, hint_bn = excluded.hint_bn, sensitive = excluded.sensitive, sla_hours = excluded.sla_hours, suggested_department_id = excluded.suggested_department_id, active = excluded.active;
insert into public.categories (id, en, bn, hint_en, hint_bn, sensitive, sla_hours, suggested_department_id, active) values ('lighting', 'Lighting & Electricity', 'আলো ও বিদ্যুৎ', 'Add the pole or room number if you can see one.', 'খুঁটি বা কক্ষ নম্বর দেখতে পেলে যোগ করুন।', false, 48, 'd-elec', true) on conflict (id) do update set en = excluded.en, bn = excluded.bn, hint_en = excluded.hint_en, hint_bn = excluded.hint_bn, sensitive = excluded.sensitive, sla_hours = excluded.sla_hours, suggested_department_id = excluded.suggested_department_id, active = excluded.active;
insert into public.categories (id, en, bn, hint_en, hint_bn, sensitive, sla_hours, suggested_department_id, active) values ('water', 'Water Supply & Sanitation', 'পানি সরবরাহ ও স্যানিটেশন', 'Say whether the water is off, leaking, or not draining.', 'পানি বন্ধ, লিক, নাকি নামছে না — তা লিখুন।', false, 48, 'd-water', true) on conflict (id) do update set en = excluded.en, bn = excluded.bn, hint_en = excluded.hint_en, hint_bn = excluded.hint_bn, sensitive = excluded.sensitive, sla_hours = excluded.sla_hours, suggested_department_id = excluded.suggested_department_id, active = excluded.active;
insert into public.categories (id, en, bn, hint_en, hint_bn, sensitive, sla_hours, suggested_department_id, active) values ('cleanliness', 'Cleanliness & Waste Management', 'পরিচ্ছন্নতা ও বর্জ্য ব্যবস্থাপনা', 'Mention how long the waste has been sitting there.', 'বর্জ্য কতক্ষণ ধরে পড়ে আছে তা লিখুন।', false, 36, 'd-clean', true) on conflict (id) do update set en = excluded.en, bn = excluded.bn, hint_en = excluded.hint_en, hint_bn = excluded.hint_bn, sensitive = excluded.sensitive, sla_hours = excluded.sla_hours, suggested_department_id = excluded.suggested_department_id, active = excluded.active;
insert into public.categories (id, en, bn, hint_en, hint_bn, sensitive, sla_hours, suggested_department_id, active) values ('safety', 'Campus Safety & Security', 'ক্যাম্পাস নিরাপত্তা', 'If someone is in immediate danger, call 999. This report is for follow-up, not rescue.', 'কেউ তাৎক্ষণিক বিপদে থাকলে ৯৯৯-এ কল করুন। এই রিপোর্ট ফলোআপের জন্য, উদ্ধারের জন্য নয়।', false, 12, 'd-sec', true) on conflict (id) do update set en = excluded.en, bn = excluded.bn, hint_en = excluded.hint_en, hint_bn = excluded.hint_bn, sensitive = excluded.sensitive, sla_hours = excluded.sla_hours, suggested_department_id = excluded.suggested_department_id, active = excluded.active;
insert into public.categories (id, en, bn, hint_en, hint_bn, sensitive, sla_hours, suggested_department_id, active) values ('harassment', 'Harassment & Discrimination', 'হয়রানি ও বৈষম্য', 'You can hide your name. Write what happened, when, and where. You do not have to name anyone to submit.', 'নাম লুকাতে পারবেন। কী হয়েছে, কখন এবং কোথায় — তা লিখুন। জমা দিতে কারও নাম দেওয়া বাধ্যতামূলক নয়।', true, 24, 'd-affairs', true) on conflict (id) do update set en = excluded.en, bn = excluded.bn, hint_en = excluded.hint_en, hint_bn = excluded.hint_bn, sensitive = excluded.sensitive, sla_hours = excluded.sla_hours, suggested_department_id = excluded.suggested_department_id, active = excluded.active;
insert into public.categories (id, en, bn, hint_en, hint_bn, sensitive, sla_hours, suggested_department_id, active) values ('classroom', 'Classroom & Laboratory Issues', 'শ্রেণিকক্ষ ও গবেষণাগার', 'Include the room number and whether teaching is blocked.', 'কক্ষ নম্বর লিখুন এবং ক্লাস বন্ধ হচ্ছে কি না বলুন।', false, 48, 'd-maint', true) on conflict (id) do update set en = excluded.en, bn = excluded.bn, hint_en = excluded.hint_en, hint_bn = excluded.hint_bn, sensitive = excluded.sensitive, sla_hours = excluded.sla_hours, suggested_department_id = excluded.suggested_department_id, active = excluded.active;
insert into public.categories (id, en, bn, hint_en, hint_bn, sensitive, sla_hours, suggested_department_id, active) values ('internet', 'Internet & Technology Problems', 'ইন্টারনেট ও প্রযুক্তি', 'Name the network, the building, and whether other people are affected.', 'নেটওয়ার্ক, ভবন, এবং অন্যরাও আক্রান্ত কি না লিখুন।', false, 36, 'd-it', true) on conflict (id) do update set en = excluded.en, bn = excluded.bn, hint_en = excluded.hint_en, hint_bn = excluded.hint_bn, sensitive = excluded.sensitive, sla_hours = excluded.sla_hours, suggested_department_id = excluded.suggested_department_id, active = excluded.active;
insert into public.categories (id, en, bn, hint_en, hint_bn, sensitive, sla_hours, suggested_department_id, active) values ('accessibility', 'Accessibility Issues', 'প্রবেশগম্যতা', 'Say what blocks access: lift, ramp, door, signage, or seating.', 'কী বাধা দিচ্ছে তা লিখুন: লিফট, র‍্যাম্প, দরজা, সাইন, বা আসন।', false, 48, 'd-maint', true) on conflict (id) do update set en = excluded.en, bn = excluded.bn, hint_en = excluded.hint_en, hint_bn = excluded.hint_bn, sensitive = excluded.sensitive, sla_hours = excluded.sla_hours, suggested_department_id = excluded.suggested_department_id, active = excluded.active;
insert into public.categories (id, en, bn, hint_en, hint_bn, sensitive, sla_hours, suggested_department_id, active) values ('other', 'Other Campus Problems', 'অন্যান্য ক্যাম্পাস সমস্যা', 'Use the closest category if you can. It helps the right office see the report.', 'সম্ভব হলে কাছাকাছি বিভাগ বেছে নিন। সঠিক দপ্তর তাহলে রিপোর্ট দেখতে পায়।', false, 72, 'd-maint', true) on conflict (id) do update set en = excluded.en, bn = excluded.bn, hint_en = excluded.hint_en, hint_bn = excluded.hint_bn, sensitive = excluded.sensitive, sla_hours = excluded.sla_hours, suggested_department_id = excluded.suggested_department_id, active = excluded.active;
